-- Handbook metadata, zero-unit seminars, elective routing and canonical course identities.
begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir ../helpers/legal-fixtures.inc
create function pg_temp.new_user(p_name text) returns uuid language plpgsql as $$
declare v uuid:=gen_random_uuid(); begin
  insert into auth.users(id,email,raw_user_meta_data) values(v,v::text||'@expanded-curriculum.test',jsonb_build_object('display_name',p_name)); return v;
end $$;
create function pg_temp.login(p_user uuid) returns void language plpgsql as $$ begin
  perform set_config('request.jwt.claims',json_build_object('sub',p_user,'role','authenticated')::text,true);
  perform set_config('request.jwt.claim.sub',p_user::text,true); perform set_config('role','authenticated',true);
end $$;
select set_config('t.uni',(select id::text from public.universities where slug='adeleke-university-ede-osun-state'),true) is not null as setup;
select set_config('t.faculty',(select id::text from public.faculties where university_id=current_setting('t.uni')::uuid and name='Faculty of Science'),true) is not null as setup;
select set_config('t.cs',(select id::text from public.departments where faculty_id=current_setting('t.faculty')::uuid and name='Computer Science'),true) is not null as setup;
select set_config('t.period',(select id::text from public.academic_periods where university_id=current_setting('t.uni')::uuid and label='2026/2027'),true) is not null as setup;
select set_config('t.first',(select id::text from public.semesters where academic_period_id=current_setting('t.period')::uuid and sort_order=1),true) is not null as setup;
select set_config('t.second',(select id::text from public.semesters where academic_period_id=current_setting('t.period')::uuid and sort_order=2),true) is not null as setup;
select set_config('t.l100',(select id::text from public.levels where university_id=current_setting('t.uni')::uuid and label='100 Level'),true) is not null as setup;
select set_config('t.l300',(select id::text from public.levels where university_id=current_setting('t.uni')::uuid and label='300 Level'),true) is not null as setup;
select is((select count(*)::integer from public.curriculum_courses where university_id=current_setting('t.uni')::uuid),213,'213 programme requirements, without duplicate old entries');
select is((select count(distinct course_id)::integer from public.curriculum_courses where university_id=current_setting('t.uni')::uuid),105,'105 canonical course identities');
select is((select count(*)::integer from public.course_offerings where semester_id=current_setting('t.first')::uuid),118,'first semester has 118 programme-level offerings');
select is((select count(*)::integer from public.course_offerings where semester_id=current_setting('t.second')::uuid),95,'second semester has 95 programme-level offerings');
select is((select count(*)::integer from public.curriculum_courses where level_id=current_setting('t.l100')::uuid and department_id<>current_setting('t.cs')::uuid),36,'shared first-year list adds 36 requirements for CYB and SEN');
select is((select count(*)::integer from public.levels where university_id=current_setting('t.uni')::uuid and label='400 Level'),1,'400-level tables now imported from complete PDF');
select is((select count(*)::integer from public.courses where code='CSC 203'),1,'existing CSC 203 course retained');
select is((select count(*)::integer from public.courses where code='COS 203'),0,'COS 203 source variant does not create a duplicate');
select is((select count(*)::integer from public.curriculum_courses cc join public.courses c on c.id=cc.course_id where c.code='CSC 203' and cc.source_code='COS 203'),2,'source code retained for both handbook occurrences');
select is((select count(*)::integer from public.curriculum_courses where unit_count=0),7,'all seven zero-unit seminars retained');
select is((select count(*)::integer from public.curriculum_courses where requirement_status='E'),14,'all fourteen elective entries retain E status');
select is((select count(*)::integer from public.curriculum_courses where elective_group is not null),4,'both explicit select-one pairs form elective groups');
select ok((select lecture_hours is null from public.curriculum_courses cc join public.courses c on c.id=cc.course_id where cc.department_id=current_setting('t.cs')::uuid and c.code='CYB 305'),'obscured lecture hours are not invented');
select is((select cc.practical_hours from public.curriculum_courses cc join public.courses c on c.id=cc.course_id where cc.department_id=current_setting('t.cs')::uuid and c.code='CSC 399'),135,'SIWES practical hours preserved');
select is((select cc.lecture_hours from public.curriculum_courses cc join public.courses c on c.id=cc.course_id where cc.department_id=current_setting('t.cs')::uuid and c.code='CSC 301'),30,'CS Data Structures keeps its 30 lecture hours');
select is((select cc.lecture_hours from public.curriculum_courses cc join public.courses c on c.id=cc.course_id join public.departments d on d.id=cc.department_id where d.name='Software Engineering' and c.code='CSC 301'),15,'Software Engineering Data Structures keeps different lecture hours');

-- Catalogs expose zero units and preserve semester-specific source order.
select set_config('t.student',pg_temp.new_user('First-year CS learner')::text,true) is not null as setup;
select private.apply_academic_profile(current_setting('t.student')::uuid,current_setting('t.student')::uuid,current_setting('t.uni')::uuid,current_setting('t.faculty')::uuid,current_setting('t.cs')::uuid,current_setting('t.l100')::uuid,current_setting('t.period')::uuid,current_setting('t.second')::uuid,'initial',null,null);
select pg_temp.login(current_setting('t.student')::uuid);
select is(jsonb_array_length(public.get_catalog_v1()->'offerings'),8,'100-level second-semester student sees 8 courses');
select is(public.get_catalog_v1()->'offerings'->0->'course'->>'code','GST 112','second-semester catalog uses its own source order');
select ok(not jsonb_path_exists(public.get_catalog_v1(),'$.offerings[*].course ? (@.code == "GST 111")'),'first-semester course excluded from second-semester profile');
reset role;
select set_config('t.firstyear',pg_temp.new_user('First-semester learner')::text,true) is not null as setup;
select private.apply_academic_profile(current_setting('t.firstyear')::uuid,current_setting('t.firstyear')::uuid,current_setting('t.uni')::uuid,current_setting('t.faculty')::uuid,current_setting('t.cs')::uuid,current_setting('t.l100')::uuid,current_setting('t.period')::uuid,current_setting('t.first')::uuid,'initial',null,null);
select pg_temp.login(current_setting('t.firstyear')::uuid);
select ok(jsonb_path_exists(public.get_catalog_v1(),'$.offerings[*] ? (@.unit_count == 0 && @.requirement_status == "R")'),'zero-unit R seminar appears in catalog');
reset role;

-- Elective choice is protected in the production enrollment RPC, including replay behavior.
select set_config('t.thirdyear',pg_temp.new_user('Third-year CS learner')::text,true) is not null as setup;
select private.apply_academic_profile(current_setting('t.thirdyear')::uuid,current_setting('t.thirdyear')::uuid,current_setting('t.uni')::uuid,current_setting('t.faculty')::uuid,current_setting('t.cs')::uuid,current_setting('t.l300')::uuid,current_setting('t.period')::uuid,current_setting('t.first')::uuid,'initial',null,null);
select set_config('t.e1',(select o.id::text from public.course_offerings o join public.courses c on c.id=o.course_id where o.department_id=current_setting('t.cs')::uuid and o.semester_id=current_setting('t.first')::uuid and c.code='CYB 305'),true) is not null as setup;
select set_config('t.e2',(select o.id::text from public.course_offerings o join public.courses c on c.id=o.course_id where o.department_id=current_setting('t.cs')::uuid and o.semester_id=current_setting('t.first')::uuid and c.code='INS 311'),true) is not null as setup;
select pg_temp.login(current_setting('t.thirdyear')::uuid);
select is((select count(*)::integer from jsonb_array_elements(public.get_catalog_v1()->'offerings') x where x->>'elective_group'='cs-300-first-select-one'),2,'elective alternatives identified in catalog');
select is((public.enroll_course_v1(current_setting('t.e1')::uuid,gen_random_uuid())->>'active')::boolean,true,'first elective can be enrolled');
select is((public.enroll_course_v1(current_setting('t.e1')::uuid,gen_random_uuid())->>'active')::boolean,true,'re-enrolling same elective is idempotent');
select throws_ok($$select public.enroll_course_v1(current_setting('t.e2')::uuid,gen_random_uuid())$$,'PT422','VALIDATION_FAILED','second elective from the same select-one group rejected');
select is((public.get_course_overview_v1(current_setting('t.e1')::uuid)->>'practical_hours')::integer,45,'hours propagate through course overview');
reset role;
update public.enrollments set ended_at=now() where user_id=current_setting('t.thirdyear')::uuid and offering_id=current_setting('t.e1')::uuid;
select pg_temp.login(current_setting('t.thirdyear')::uuid);
select is((public.enroll_course_v1(current_setting('t.e2')::uuid,gen_random_uuid())->>'active')::boolean,true,'ended elective no longer blocks another choice');
reset role;
select lives_ok($$select private.materialize_curriculum(current_setting('t.first')::uuid)$$,'expanded curriculum resync safe');
select is((select count(*)::integer from public.course_offerings where semester_id=current_setting('t.first')::uuid),118,'resync does not duplicate expanded first-semester offerings');
select throws_ok($$update public.curriculum_courses set unit_count=-1$$,'23514',null,'negative course units remain invalid');
select throws_ok($$update public.curriculum_courses set lecture_hours=-1$$,'23514',null,'negative contact hours remain invalid');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='100 Level' and cc.semester_number=1),10,'Computer Science 100 semester 1 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='100 Level' and cc.semester_number=1),19,'Computer Science 100 semester 1 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='100 Level' and cc.semester_number=2),8,'Computer Science 100 semester 2 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='100 Level' and cc.semester_number=2),17,'Computer Science 100 semester 2 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='200 Level' and cc.semester_number=1),10,'Computer Science 200 semester 1 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='200 Level' and cc.semester_number=1),21,'Computer Science 200 semester 1 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='200 Level' and cc.semester_number=2),9,'Computer Science 200 semester 2 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='200 Level' and cc.semester_number=2),19,'Computer Science 200 semester 2 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='300 Level' and cc.semester_number=1),8,'Computer Science 300 semester 1 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='300 Level' and cc.semester_number=1),20,'Computer Science 300 semester 1 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='300 Level' and cc.semester_number=2),7,'Computer Science 300 semester 2 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Computer Science' and l.label='300 Level' and cc.semester_number=2),18,'Computer Science 300 semester 2 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Cybersecurity' and l.label='200 Level' and cc.semester_number=1),9,'Cybersecurity 200 semester 1 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Cybersecurity' and l.label='200 Level' and cc.semester_number=1),19,'Cybersecurity 200 semester 1 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Cybersecurity' and l.label='200 Level' and cc.semester_number=2),8,'Cybersecurity 200 semester 2 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Cybersecurity' and l.label='200 Level' and cc.semester_number=2),17,'Cybersecurity 200 semester 2 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Cybersecurity' and l.label='300 Level' and cc.semester_number=1),7,'Cybersecurity 300 semester 1 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Cybersecurity' and l.label='300 Level' and cc.semester_number=1),16,'Cybersecurity 300 semester 1 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Cybersecurity' and l.label='300 Level' and cc.semester_number=2),7,'Cybersecurity 300 semester 2 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Cybersecurity' and l.label='300 Level' and cc.semester_number=2),16,'Cybersecurity 300 semester 2 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Software Engineering' and l.label='200 Level' and cc.semester_number=1),9,'Software Engineering 200 semester 1 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Software Engineering' and l.label='200 Level' and cc.semester_number=1),19,'Software Engineering 200 semester 1 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Software Engineering' and l.label='200 Level' and cc.semester_number=2),10,'Software Engineering 200 semester 2 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Software Engineering' and l.label='200 Level' and cc.semester_number=2),22,'Software Engineering 200 semester 2 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Software Engineering' and l.label='300 Level' and cc.semester_number=1),7,'Software Engineering 300 semester 1 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Software Engineering' and l.label='300 Level' and cc.semester_number=1),18,'Software Engineering 300 semester 1 listed-option unit total');
select is((select count(*)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Software Engineering' and l.label='300 Level' and cc.semester_number=2),8,'Software Engineering 300 semester 2 course count');
select is((select sum(cc.unit_count)::integer from public.curriculum_courses cc join public.departments d on d.id=cc.department_id join public.levels l on l.id=cc.level_id where d.name='Software Engineering' and l.label='300 Level' and cc.semester_number=2),19,'Software Engineering 300 semester 2 listed-option unit total');
select * from finish();
rollback;
